int secondLargestSort(int[] a) {
    Arrays.sort(a);                       // O(n log n)
    for (int i = a.length - 2; i >= 0; i--)
        if (a[i] != a[a.length - 1]) return a[i];   // skip duplicates of max
    throw new IllegalArgumentException("no distinct second");
}
