import java.util.OptionalInt;

OptionalInt secondLargest(int[] values) {
    long largest = Long.MIN_VALUE;
    long second = Long.MIN_VALUE;

    for (int value : values) {
        if (value > largest) {
            second = largest;
            largest = value;
        } else if (value < largest && value > second) {
            second = value;
        }
    }

    return second == Long.MIN_VALUE
            ? OptionalInt.empty()
            : OptionalInt.of((int) second);
}

// [10, 5, 10, 8] -> OptionalInt[8]
// [7, 7] -> OptionalInt.empty
// [0, Integer.MIN_VALUE] -> OptionalInt[Integer.MIN_VALUE]
```

